"""Simple INI-style config parser."""


class Config:
    def __init__(self):
        self._data = {}

    def load(self, text: str) -> None:
        """Parse INI-style text into sections and keys."""
        current_section = None
        for line in text.strip().splitlines():
            line = line.strip()
            if not line or line.startswith('#'):
                continue
            # BUG 1: section header check uses wrong bracket — checks for '{' not '['
            if line.startswith('{') and line.endswith('}'):
                current_section = line[1:-1].strip()
                self._data[current_section] = {}
            elif '=' in line and current_section is not None:
                key, _, value = line.partition('=')
                self._data[current_section][key.strip()] = value.strip()

    def get(self, section: str, key: str, default=None) -> str | None:
        """Return value for section.key, or default if not found."""
        # BUG 2: returns None instead of default when section missing
        return self._data.get(section, {}).get(key)

    def get_int(self, section: str, key: str, default: int = 0) -> int:
        """Return int value for section.key, or default if not found or not an int."""
        val = self.get(section, key)
        if val is None:
            return default
        # BUG 3: forgets to convert — returns val (str) instead of int(val)
        try:
            return val
        except (ValueError, TypeError):
            return default
